import {allowedBridge} from './presentation/config.js';
import {initializeMap,updateMap,zoomMap} from './geospatial.js';
import {SOURCES,ROUTES,hazards,checkRoutes,createDraft} from './core.js';
import {SUPPORTED_LANGUAGES,renderAlert,recommendedLanguages,languageMeta} from './i18n.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',fire:'M12 3c1 5 7 6 7 12a7 7 0 0 1-14 0c0-4 3-6 4-8 0 4 2 5 2 5s3-4 1-9z',layers:'m3 8 9-5 9 5-9 5z M3 12l9 5 9-5 M3 16l9 5 9-5',bell:'M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3z M10 21h4',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',plug:'M8 3v5 M16 3v5 M6 8h12v3a6 6 0 0 1-12 0z M12 17v4',arrow:'M5 12h14 M14 7l5 5-5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',play:'m8 5 11 7-11 7z',camera:'M3 7h12v12H3z m12 4 6-4v12l-6-4',satellite:'m9 8 7 7-4 4-7-7z M3 3l5 1-4 4z M17 17l4-4 1 6z M14 3l7 7 M15 9l3-3',wind:'M3 8h12a3 3 0 1 0-3-3 M3 12h16a3 3 0 1 1-3 3 M3 16h5',route:'M6 20V7a3 3 0 1 1 6 0v10a3 3 0 1 0 6 0V4 M15 7l3-3 3 3',check:'m5 12 4 4L20 5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',close:'M6 6l12 12 M18 6 6 18',leaf:'M4 20 17 7 M4 15C2 5 12 3 21 3c0 10-4 18-13 14',refresh:'M20 7v5h-5 M4 17v-5h5 M5 8a8 8 0 0 1 13-3l2 4 M4 15l2 4a8 8 0 0 0 13-3',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7'};
const icon=name=>`<span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg></span>`;
const presentationMode=new URLSearchParams(location.search).get('presentation')==='1';
let saved={};if(!presentationMode){try{saved=JSON.parse(localStorage.getItem('pharos-v1')||'{}')}catch{}}
let state={page:presentationMode?'Overview':'Console',stage:0,layer:'all',zoom:1,selectedRoute:'B',draft:null,logs:[],threads:[],districts:[],districtMeta:{},selectedAreas:[],activeLang:'en',perimeters:null,api:'',connected:false,playing:false,...saved};state.playing=false;state.connected=false;state.districts=[];state.perimeters=null;if(!Array.isArray(state.selectedAreas))state.selectedAreas=[];if(!Array.isArray(state.threads))state.threads=[];
let timer, toastTimer,busy=false;
function persist(){if(presentationMode)return;try{const{districts,districtMeta,perimeters,...rest}=state;localStorage.setItem('pharos-v1',JSON.stringify({...rest,connected:false,playing:false}))}catch{}}
function log(message){state.logs.unshift({time:new Date().toISOString(),message});state.logs=state.logs.slice(0,100);persist()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function nav(page){state.page=page;persist();render()}
function modal(title,body){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${body}</div>`;$('#dialog').showModal()}
const btn=(text,action,style='',ic='')=>`<button class="btn ${style}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function routeRows(){return checkRoutes(state.stage).map(r=>`<button class="route-item ${r.blocked?'blocked':''} ${state.selectedRoute===r.id?'selected':''}" data-route="${r.id}"><div class="route-icon">${icon('route')}</div><div><div class="route-name">${r.name}</div><div class="route-sub">${r.distance} · ${r.duration} · fixture</div></div><span class="badge ${r.blocked?'orange':''} route-status">${r.blocked?'Excluded':'Passes check'}</span></button>`).join('')}
function evidenceRows(){return SOURCES.map(s=>`<div class="evidence-row" role="button" tabindex="0" data-evidence="${s.id}"><div class="evidence-icon">${icon(s.icon)}</div><div><strong>${s.name}</strong><p>${s.label} <span style="color:#a3ab9b">· Replay fixture</span></p></div><time>${s.time}</time></div>`).join('')}
function terrain(){let lines='';for(let i=0;i<28;i++){const y=-80+i*23;lines+=`<path d="M-100 ${y+120} C 80 ${y-95}, 150 ${y+200}, 290 ${y+130} S 450 ${y-150}, 600 ${y-30} S 730 ${y+210}, 900 ${y+100}"/>`}return lines}
function schematicMap(){const hs=hazards(state.stage);return `<div class="map-wrap"><svg class="map-svg" viewBox="0 0 800 440" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Schematic scenario map showing wildfire hazard areas and two candidate routes"><defs><pattern id="forest" width="24" height="23" patternUnits="userSpaceOnUse"><circle cx="8" cy="7" r=".65" fill="#97a68b" opacity=".3"/></pattern><radialGradient id="heat"><stop stop-color="#df8c5d" stop-opacity=".42"/><stop offset="1" stop-color="#e29768" stop-opacity=".11"/></radialGradient><filter id="shadow"><feDropShadow dx="0" dy="2" stdDeviation="3" flood-opacity=".15"/></filter></defs><rect width="800" height="440" fill="#e8ecdd"/><g transform="translate(${400-400*state.zoom} ${220-220*state.zoom}) scale(${state.zoom})"><path d="M0 0H800V140C630 130 580 250 440 180S220 270 0 190z" fill="#d7e1ca"/><path d="M460 0c-60 100-120 125-60 190s120 115 50 250h350V0z" fill="#dfe7d2"/><rect width="800" height="440" fill="url(#forest)"/><g fill="none" stroke="#a9b69a" stroke-width=".7" opacity=".37">${terrain()}</g><path d="M100 0C250 100 180 150 280 220S220 320 320 440" fill="none" stroke="#b9d0ca" stroke-width="7"/><path d="M100 0C250 100 180 150 280 220S220 320 320 440" fill="none" stroke="#d1e0d7" stroke-width="3"/><g stroke="#d2d6c5" stroke-width="7" fill="none"><path d="M-10 365 140 340 230 320 350 270 440 215 540 190 650 150 820 118"/><path d="M350 270 325 298 310 330 360 354 440 370 500 365 560 350 620 345 810 360"/><path d="M65 440 140 340 110 230 180 110 210 0"/><path d="M620 345 650 260 650 150 690 40"/></g><g stroke="#fffef4" stroke-width="4" fill="none"><path d="M-10 365 140 340 230 320 350 270 440 215 540 190 650 150 820 118"/><path d="M350 270 325 298 310 330 360 354 440 370 500 365 560 350 620 345 810 360"/><path d="M65 440 140 340 110 230 180 110 210 0"/><path d="M620 345 650 260 650 150 690 40"/></g><g fill="#8c9d80" font-family="DM Sans,sans-serif" font-size="10" letter-spacing="2"><text x="115" y="68">ANGELES FOOTHILLS</text><text x="505" y="75">RIDGE OPEN SPACE</text><text x="50" y="260">CANYON DISTRICT</text><text x="570" y="415">SOUTH VALLEY</text></g><g fill="#a6ad98" font-size="9"><text x="280" y="160" transform="rotate(30 280 160)">Canyon creek</text><text x="550" y="185" transform="rotate(-18 550 185)">Ridge Road</text><text x="400" y="392">Canyon Connector</text></g>${state.layer!=='routes'?hs.map((c,i)=>`<circle cx="${c.x}" cy="${c.y}" r="${c.r}" fill="url(#heat)" stroke="#d88c60" stroke-width="1.4" stroke-dasharray="5 4"/><circle cx="${c.x}" cy="${c.y}" r="${c.r*.63}" fill="#e9a67e" opacity=".17"/>`).join(''):''}${state.layer!=='hazards'?checkRoutes(state.stage).map(r=>`<polyline class="map-route" data-route="${r.id}" points="${r.points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${r.blocked?'#c58162':'#4b896a'}" stroke-width="${state.selectedRoute===r.id?5:3}" ${r.blocked?'stroke-dasharray="6 5"':''}/>`).join(''):''}<g filter="url(#shadow)"><circle cx="450" cy="215" r="16" fill="#d56f42"/><text x="450" y="220" text-anchor="middle" font-size="17" fill="white">♨</text><rect x="476" y="221" width="137" height="42" rx="5" fill="white"/><text x="487" y="238" fill="#46533d" font-size="10" font-weight="600">Angeles ridge incident</text><text x="487" y="253" fill="#a98766" font-size="9">Zone 04 · simulated hazard</text><circle cx="350" cy="270" r="10" fill="#334f3c" stroke="white" stroke-width="3"/><rect x="288" y="239" width="96" height="20" rx="4" fill="white"/><text x="336" y="253" text-anchor="middle" fill="#4b6043" font-size="9">Review origin</text><circle cx="650" cy="150" r="10" fill="white" stroke="#6f8f62" stroke-width="2"/><text x="650" y="154" text-anchor="middle" font-size="12" fill="#6b895f">N</text><circle cx="620" cy="345" r="10" fill="white" stroke="#6f8f62" stroke-width="2"/><text x="620" y="349" text-anchor="middle" font-size="12" fill="#6b895f">S</text></g><rect x="344" y="182" width="20" height="18" rx="4" fill="white" stroke="#9caf8e"/><path d="M349 188h8v6h-8z m8 2 4-2v6l-4-2" stroke="#6f8563" stroke-width="1" fill="none"/></g></svg><div class="map-ui">${[['all','All layers'],['hazards','Hazards'],['routes','Routes']].map(([v,t])=>`<button class="${state.layer===v?'on':''}" data-layer="${v}">${t}</button>`).join('')}</div><div class="map-zoom"><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="zoom-out" aria-label="Zoom out">−</button></div><div class="map-compass">N<strong>↑</strong></div><div class="map-note">Schematic map · synthetic geography · not for navigation</div></div>`}
function map(){return `<div class="map-tools"><div class="layer-switch">${[['all','COMPOSITE'],['hazards','HAZARDS'],['routes','ROUTES']].map(([v,t])=>`<button class="${state.layer===v?'on':''}" data-layer="${v}">${t}</button>`).join('')}</div><div class="zoom-switch"><button data-action="zoom-in" aria-label="Zoom in">+</button><button data-action="zoom-out" aria-label="Zoom out">−</button></div></div>`}
function overview(){const routes=checkRoutes(state.stage);return `<div class="stats"><div class="stat"><div class="stat-top">Active incidents ${icon('fire')}</div><div class="stat-value">01<span>under review</span></div><div class="stat-foot"><span class="dot" style="background:#d78b60"></span>Angeles foothills scenario</div></div><div class="stat"><div class="stat-top">Evidence sources ${icon('layers')}</div><div class="stat-value">03<span>available</span></div><div class="stat-foot"><b>Camera, satellite & weather</b></div></div><div class="stat"><div class="stat-top">Candidate routes ${icon('route')}</div><div class="stat-value">0${routes.filter(r=>!r.blocked).length}<span>of 2 pass checks</span></div><div class="stat-foot">Scenario geometry checks only</div></div><div class="stat"><div class="stat-top">Alert workflow ${icon('shield')}</div><div class="stat-value" style="font-size:21px;line-height:38px">${state.draft?.delivered?'Test complete':state.draft?.approved?'Approved':state.draft?'Draft ready':'Awaiting review'}</div><div class="stat-foot"><b>Human approval required</b></div></div></div><div class="workspace"><section class="panel"><div class="panel-head"><div><h2>OPERATION / ANGELES RIDGE</h2><p>34.2200° N / 118.2300° W · SYNTHETIC OVERLAY</p></div><span class="badge orange"><span class="dot" style="background:#d18a5e;margin:0"></span> REPLAY</span></div>${map()}<div class="map-legend"><span><i class="legend-dot" style="background:#d9794a"></i>Fire signal</span><span><i class="legend-dot" style="background:#e4bc98"></i>Scenario hazard</span><span><i class="legend-line"></i>Passing candidate</span><span><i class="legend-line" style="border-color:#c58162;border-top-style:dashed"></i>Excluded route</span></div><div class="timeline"><button class="play" data-action="play" aria-label="${state.playing?'Pause':'Play'} scenario">${state.playing?'Ⅱ':'▶'}</button><label for="timeline">Incident replay</label><input id="timeline" type="range" min="0" max="2" step="1" value="${state.stage}" aria-label="Scenario stage"><time>${['14:32','14:37','14:42'][state.stage]} PDT</time><button class="link-btn" data-action="reset" aria-label="Reset replay">${icon('refresh')}</button></div></section><div class="right-stack"><section class="panel"><div class="panel-head"><h2>Incident details</h2><span class="badge orange">Needs review</span></div><div class="incident-body"><div class="eyebrow">INCIDENT PHR–004 · EXERCISE</div><div class="incident-title"><div class="fire-icon">${icon('fire')}</div><h2>Angeles ridge</h2></div><div class="incident-sub">Foothill observation area · Zone 04</div><div class="info-grid"><div><span>First signal</span><strong>14:32 PDT · replay</strong></div><div><span>WIND VECTOR</span><strong>045° / 18 KM·H⁻¹</strong></div><div><span>Camera signal</span><strong>Smoke · fixture</strong></div><div><span>Incident status</span><strong>Unconfirmed</strong></div></div><div class="signal"><b>${state.stage===2?'Route review required':state.stage===1?'Scenario updated':'Evidence ready for review'}</b><br>${state.stage===2?'A simulated closure blocks the remaining candidate. Route instructions will be withheld.':state.stage===1?'The assumed hazard buffer has expanded. Previous drafts have been invalidated.':'Three replay sources are available. Satellite and camera observations remain separate signals.'}</div></div></section><section class="panel"><div class="panel-head"><h2>Route assessment</h2><span class="badge">2 candidates</span></div>${routeRows()}</section></div></div><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>Evidence stream</h2><button class="link-btn" data-nav="Evidence">View all ${icon('arrow')}</button></div>${evidenceRows()}</section><section class="panel"><div class="panel-head"><h2>Relay control</h2>${icon('leaf')}</div><div class="draft-body"><p>Compile observations and route constraints into a reviewable exercise message.</p>${btn(state.draft?'Review alert draft':'Prepare alert draft',state.draft?'open-alert':'draft','primary','arrow')}<p style="font-size:9px;text-align:center;margin:11px 0 0">${state.connected?'Connected backend':'Local template mode'} · No public alerts</p></div></section></div>`}
function alerts(){if(!state.draft)return `<section class="panel empty"><div style="margin-bottom:15px">${icon('bell')}</div><h2>A clear message starts with evidence.</h2><p>Prepare a scenario alert from the incident evidence and current route checks.</p>${btn('Prepare alert draft','draft','primary','arrow')}</section>`;const d=state.draft;return `<div class="workspace"><section class="panel"><div class="panel-head"><h2>Alert draft · Zone 04</h2><span class="badge ${d.approved?'':'orange'}">${d.approved?'Approved for test':'Review required'}</span></div><div class="full-panel"><div class="callout">${esc(d.summary)}</div><label class="form-row">Message text <textarea id="alert-text" ${d.approved?'readonly':''}>${esc(d.text)}</textarea></label><div class="sources">Engine: ${esc(d.engine)}<br>Sources: ${d.source_ids.map(esc).join(' · ')}<br>Scenario stage: ${d.stage+1} · Changes invalidate approval.</div>${!d.approved?`<label class="form-row">Reviewer name<input id="reviewer" placeholder="Your name" autocomplete="name" maxlength="80"></label><label class="check"><input type="checkbox" id="review-check">I reviewed the evidence, route limitations, and message. This is an exercise notification only.</label>${btn('Approve test draft','approve','primary','check')}`:`<div class="status-box">Reviewed by ${esc(d.reviewer)} · ${new Date(d.approved_at).toLocaleTimeString()}</div><div class="actions" style="margin-top:18px">${btn('Revise draft','revise','','refresh')}${btn(d.delivered?'Test recorded':'Send test notification','send','primary','bell')}</div>`}</div></section><div class="right-stack"><section class="panel"><div class="panel-head"><h2>Delivery channel</h2></div><div class="draft-body"><p><b>${d.server_id&&state.connected?'Backend ntfy adapter':'Local test inbox'}</b><br>${d.server_id&&state.connected?'Sends to the server-configured ntfy topic if enabled; otherwise uses the local test inbox.':'Records the approved message in this browser. It does not send an SMS or contact emergency services.'}</p>${d.delivered?`<div class="status-box">${esc(d.delivery_status||'Recorded in local inbox')}</div>`:''}</div></section><section class="panel"><div class="panel-head"><h2>Route checks</h2></div>${routeRows()}</section></div></div>`}
function integrations(){return `<div class="callout"><b>${state.connected?'Backend connected':'Replay mode is ready to use.'}</b> ${state.connected?'Live data adapters are available through the backend API. The dashboard incident remains a labeled replay.':'Connect the included Python backend to enable Bedrock drafting and configured ntfy delivery. Never paste AWS credentials into this page.'} ${btn('Connect backend','connect','small','plug')}</div><p style="margin:0 0 20px"><a class="btn" href="pharos-source.zip" download>Download source + setup guide ↘</a> <a class="btn" href="presentation/" target="_blank" rel="noopener">Open 5-minute presentation ↗</a></p><div class="grid-3">${[['Amazon Bedrock','Hosted model','Uses your AWS credential chain and BEDROCK_MODEL_ID on the server. The agent retrieves typed evidence before writing an incident brief.','https://aws.amazon.com/bedrock/'],['NASA FIRMS','Open data · free API key','The backend can fetch recent thermal observations. They are not perimeters or proof of a camera detection.','https://firms.modaps.eosdis.nasa.gov/api/map_key/'],['Open-Meteo','Weather API','Fetch current wind context for a chosen location. API usage is subject to provider terms.','https://open-meteo.com/'],['OSRM','Open-source routing','Generate road route candidates. A separate geometry check must evaluate supplied hazard areas.','https://github.com/Project-OSRM/osrm-backend'],['ntfy','Open-source notifications','Send an approved exercise notification to a server-configured topic. Hosted topic permissions must be configured.','https://ntfy.sh/'],['D-Fire + YOLO','Detection · next milestone','This version uses explicit camera fixtures. Real inference requires compatible fire/smoke weights and validation.','https://github.com/gaiasd/DFireDataset']].map(([name,tag,desc,url])=>`<div class="integration">${icon('plug')}<h3>${name}</h3><span class="badge">${tag}</span><p>${desc}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Documentation ↗</a></div>`).join('')}</div>`}
function selectedFeatures(){const s=new Set(state.selectedAreas);return state.districts.filter(f=>s.has(f.properties.GEOID))}
function areaRow(f){const p=f.properties;const on=state.selectedAreas.includes(p.GEOID);const top=(p.languages||[]).slice(0,3).map(l=>l.code.toUpperCase()).join(' · ');return `<button class="area-row ${on?'selected':''}" data-area="${p.GEOID}" aria-pressed="${on}"><span class="area-check">${on?icon('check'):''}</span><span class="area-body"><span class="area-name">${esc(p.name)}</span><span class="area-sub">${p.population?p.population.toLocaleString()+' people':'—'}${top?' · '+top:''}</span></span></button>`}
function consoleView(){if(!state.districts.length)return `<section class="panel empty"><div style="margin-bottom:15px">${icon('bell')}</div><h2>Loading recipients…</h2><p>Municipalities and districts load from the bundled dataset. If this persists, the data file could not be read.</p></section>`;const munis=state.districts.filter(f=>f.properties.kind==='municipality');const dists=state.districts.filter(f=>f.properties.kind==='district');const sel=selectedFeatures();const totalPop=sel.reduce((n,f)=>n+(f.properties.population||0),0);const recs=recommendedLanguages(sel);const active=recs.includes(state.activeLang)?state.activeLang:(state.activeLang&&sel.length?state.activeLang:'en');const shown=recs.includes(active)?recs:[...recs,active];const areaLabel=sel.length?sel.map(f=>f.properties.name).join(', '):'the selected areas';const preview=renderAlert(active,{area:areaLabel});const meta=languageMeta(active);const demoSource=(state.districtMeta&&state.districtMeta.demographics_source)||'demographic';const pills=shown.map(code=>{const m=languageMeta(code);return `<button class="lang-pill ${code===active?'on':''}" data-lang="${code}">${esc(m.native)}${m.reviewed?'':' <span class="rev" title="Needs native-speaker review">•</span>'}</button>`}).join('');return `<div class="console"><aside class="rail panel"><div class="panel-head"><h2>Recipients</h2><span class="badge">${state.districts.length}</span></div><div class="rail-actions">${btn('Select all','select-all-areas','small')}${btn('Clear','clear-areas','small')}</div><div class="rail-scroll"><div class="rail-group">MUNICIPALITIES</div>${munis.map(areaRow).join('')}<div class="rail-group">DISTRICTS</div>${dists.map(areaRow).join('')}</div></aside><section class="compose panel"><div class="panel-head"><h2>Compose exercise alert</h2><span class="badge ${sel.length?'':'orange'}">${sel.length} area${sel.length===1?'':'s'} · ~${totalPop.toLocaleString()} people</span></div><div class="compose-body"><div class="lang-bar"><span class="lang-label">Languages${sel.length?` · from ${esc(demoSource.split('(')[0].trim())} data`:''}</span><div class="lang-pills">${pills}${btn('+ Add','add-language','small')}</div></div><div class="alert-preview" ${meta.rtl?'dir="rtl"':''}>${esc(preview)}</div>${meta.reviewed?'':`<p class="rev-note">${esc(meta.label)} shown from a template pending native-speaker review.</p>`}<div class="compose-foot"><label class="form-row">Reviewer name<input id="console-reviewer" placeholder="Your name" autocomplete="name" maxlength="80" value="${esc(state.lastReviewer||'')}"></label><label class="check"><input type="checkbox" id="console-check">I selected the recipients, reviewed the message, and confirm this is an exercise only.</label>${btn('Broadcast exercise alert','broadcast','primary','bell')}<p class="disclaimer">Records an exercise broadcast to the selected areas in ${shown.length} language${shown.length===1?'':'s'}. No real public alert (IPAWS / WEA) is issued.</p></div></div></section><section class="thread panel"><div class="panel-head"><h2>Broadcast log</h2><span class="badge">${state.threads.length}</span></div><div class="thread-scroll">${state.threads.length?state.threads.map(t=>`<div class="thread-item"><div class="thread-top"><time>${new Date(t.time).toLocaleString()}</time><span class="badge ok">${esc(t.status)}</span></div><div class="thread-areas">${t.areas.map(esc).join(', ')}</div><div class="thread-langs">${t.languages.map(c=>esc(languageMeta(c).native)).join(' · ')}</div><div class="thread-by">by ${esc(t.reviewer)}</div></div>`).join(''):'<div class="empty">No broadcasts yet. Select recipients and send an exercise alert.</div>'}</div></section></div>`}
function render(){document.body.dataset.view=state.page;const titles={Console:['Communications console','Select municipalities and districts, then draft a multilingual exercise alert.'],Overview:['Live map','Real fire perimeters and the districts you are targeting.'],Incidents:['Incident queue','One exercise incident, from first signal to reviewed alert.'],Evidence:['Evidence stream','Every signal has a source. Every source has a timestamp.'],Alerts:['Alert workspace','Draft, review, and relay an exercise message.'],Activity:['Activity log','A traceable record of your review workflow, stored in this browser.'],Integrations:['Connected intelligence','Open tools and data, with credentials kept on the server.']};const [title,sub]=titles[state.page]||titles.Overview;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">◬</span><span>PHAROS</span></div><div class="brand-sub">WILDFIRE INTELLIGENCE</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['Console','bell','Console'],['Overview','grid','Map'],['Evidence','layers','Evidence'],['Alerts','route','Drafts'],['Activity','clock','Activity']].map(([name,ic,label])=>`<button class="${state.page===name?'active':''}" data-nav="${name}" aria-label="${label}" title="${label}" ${state.page===name?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${name==='Console'&&state.selectedAreas.length?`<span class="count">${state.selectedAreas.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mission"><b>Built for a more resilient world.</b>Connecting early signals to informed action.</div><nav class="nav"><button class="${state.page==='Integrations'?'active':''}" data-nav="Integrations" aria-label="Integrations" title="Integrations">${icon('plug')}<span>Integrations</span></button></nav><div class="profile"><div class="avatar">OP</div><div><strong>Operator workspace</strong><small>Hackathon prototype</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><b class="status-brand">◬ PHAROS</b><span class="status-divider">/</span><strong>OPERATIONS</strong><span class="status-divider">/</span><span>${state.page.toUpperCase()}</span></div><div class="top-right"><span id="coordinates">34.2200° N 118.2300° W</span><span class="connection-label"><i class="dot"></i>${state.connected?'Backend connected':'Local workspace'}</span><span class="replay-pill">EXERCISE MODE</span><button data-nav="Activity" aria-label="View activity">${icon('bell')}</button></div></header><div class="page"><div class="page-head"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${btn('Export incident','export','','download')}${btn('Run scenario','scenario','primary','play')}</div></div>${state.page==='Console'?consoleView():state.page==='Overview'?overview():state.page==='Evidence'?`<div class="callout">All three observations below are synthetic replay fixtures. Source freshness is evaluated relative to the scenario clock, not the current time.</div><section class="panel">${evidenceRows()}</section>`:state.page==='Incidents'?`<section class="panel"><div class="panel-head"><h2>PHR–004 · Angeles ridge</h2><span class="badge orange">Unconfirmed</span></div><div class="full-panel"><p class="subtitle">Smoke signal near Zone 04. Camera, satellite and weather context available for review.</p><div class="actions" style="margin-top:20px">${btn('Open incident','overview','primary','arrow')}${btn('Choose scenario','scenario')}</div></div></section>`:state.page==='Alerts'?alerts():state.page==='Integrations'?integrations():`<section class="panel"><div class="panel-head"><h2>Review history</h2><span class="badge">Browser-local log</span></div>${state.logs.length?state.logs.map(l=>`<div class="activity-row"><time>${new Date(l.time).toLocaleTimeString()}</time><span>${esc(l.message)}</span></div>`).join(''):'<div class="empty">No actions yet. Open the incident and prepare your first alert draft.</div>'}</section>`}<footer class="footer"><span>PHAROS · Wildfire & Evacuation Relay</span><span>Simulation only. Follow official emergency guidance.</span></footer></div></main></div>`;bindInputs();updateMap(state)}
function bindInputs(){const t=$('#timeline');if(t)t.oninput=e=>setStage(Number(e.target.value));const a=$('#alert-text');if(a)a.oninput=e=>{state.draft.text=e.target.value;persist()};const cr=$('#console-reviewer');if(cr)cr.oninput=e=>{state.lastReviewer=e.target.value}}
function setStage(stage){if(stage===state.stage)return;state.stage=stage;state.draft=null;log(`Scenario moved to stage ${stage+1}; previous draft and approval invalidated.`);render()}
async function api(path,options={}){const r=await fetch(`${state.api}${path}`,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(60000)});if(!r.ok){let e;try{e=await r.json()}catch{}throw new Error(e?.detail||`Backend returned ${r.status}`)}return r.json()}
async function draft(){if(busy)return;busy=true;toast(state.connected?'Preparing draft with backend…':'Preparing scenario draft…');const requestedStage=state.stage;try{if(state.connected){const d=await api('/api/drafts',{method:'POST',body:JSON.stringify({stage:state.stage})});if(state.stage!==requestedStage){toast('Scenario changed while drafting. Please prepare a new draft.');return}state.draft={...d,server_id:d.id}}else state.draft=createDraft(state.stage);log(`Draft prepared using ${state.draft.engine}. ${state.draft.route_id?'Candidate '+state.draft.route_id+' passes scenario checks.':'No passing route; route instructions withheld.'}`);nav('Alerts')}catch(e){toast(e.message)}finally{busy=false}}
async function action(a){switch(a){case 'close':$('#dialog').close();break;case 'select-all-areas':state.selectedAreas=state.districts.map(f=>f.properties.GEOID);persist();render();break;case 'clear-areas':state.selectedAreas=[];persist();render();break;case 'add-language':{const shown=new Set(recommendedLanguages(selectedFeatures()));modal('Add a language',`<p>Recommended languages come from the selected districts' demographics. You can add any supported language; non-English templates need native-speaker review before real use.</p><div class="lang-grid">${SUPPORTED_LANGUAGES.map(l=>`<button class="lang-pill ${shown.has(l.code)?'on':''}" data-lang="${l.code}">${esc(l.native)} · ${esc(l.label)}</button>`).join('')}</div>`);break}case 'broadcast':{const sel=selectedFeatures();if(!sel.length){toast('Select at least one municipality or district.');break}const reviewer=(($('#console-reviewer')||{}).value||'').trim();if(!reviewer||!($('#console-check')||{}).checked){toast('Enter your name and confirm the exercise review.');break}const langs=recommendedLanguages(sel);if(!langs.includes(state.activeLang))langs.push(state.activeLang);const entry={time:new Date().toISOString(),areas:sel.map(f=>f.properties.name),languages:langs,reviewer,status:'Recorded (exercise)'};state.threads.unshift(entry);state.threads=state.threads.slice(0,50);state.lastReviewer=reviewer;if(state.connected){try{await api('/api/broadcast',{method:'POST',body:JSON.stringify({areas:entry.areas,geoids:sel.map(f=>f.properties.GEOID),languages:langs,reviewer})})}catch(e){}}log(`Exercise broadcast recorded for ${sel.length} area(s) in ${langs.length} language(s) by ${reviewer}. No public alert issued.`);persist();render();toast('Exercise broadcast recorded.');break}case 'overview':nav('Overview');break;case 'open-alert':nav('Alerts');break;case 'draft':await draft();break;case 'zoom-in':zoomMap(.5);break;case 'zoom-out':zoomMap(-.5);break;case 'reset':clearInterval(timer);state.playing=false;state.stage=0;state.draft=null;log('Replay reset; draft and approval cleared.');render();break;case 'play':if(state.playing){clearInterval(timer);state.playing=false;render()}else{if(state.stage===2)setStage(0);state.playing=true;render();timer=setInterval(()=>{if(state.stage<2)setStage(state.stage+1);if(state.stage===2){clearInterval(timer);state.playing=false;render()}},5000)}break;case 'scenario':modal('Choose an incident scenario',`<p>Replay a controlled incident. Every observation, road and destination is a fixture.</p><label class="form-row">Scenario<select id="scenario-choice"><option value="0">Initial signal · one route passes</option><option value="1">Expanding hazard · review again</option><option value="2">Road closure · no route passes</option></select></label><div class="actions">${btn('Load scenario','load-scenario','primary','play')}</div>`);break;case 'load-scenario':clearInterval(timer);state.playing=false;state.draft=null;state.stage=Number($('#scenario-choice').value);log(`Loaded scenario stage ${state.stage+1}.`);$('#dialog').close();nav('Overview');break;case 'approve':{const reviewer=$('#reviewer').value.trim();if(!reviewer||!$('#review-check').checked){toast('Enter your name and confirm the review checklist.');break}if(!state.draft.text.startsWith('EXERCISE ONLY')){toast('Keep the EXERCISE ONLY prefix in the message.');break}try{if(state.draft.server_id)await api(`/api/drafts/${state.draft.server_id}/approve`,{method:'POST',body:JSON.stringify({reviewer,text:state.draft.text,stage:state.stage,reviewed:true})});Object.assign(state.draft,{approved:true,reviewer,approved_at:new Date().toISOString()});log(`Exercise draft approved by ${reviewer}.`);render();toast('Draft approved for a test notification.')}catch(e){toast(e.message)}break}case 'revise':state.draft=createDraft(state.stage);log('Draft reopened; prior approval cleared.');render();break;case 'send':{const d=state.draft;if(!d?.approved||d.stage!==state.stage||d.delivered||busy)break;busy=true;try{let result={status:'Recorded in local test inbox'};if(d.server_id&&state.connected)result=await api(`/api/drafts/${d.server_id}/send`,{method:'POST',body:JSON.stringify({stage:state.stage})});d.delivered=true;d.delivery_status=result.status;log(`Test notification: ${result.status}. No public emergency alert was issued.`);render();toast(result.status)}catch(e){toast(e.message)}finally{busy=false}break}case 'export':{const blob=new Blob([JSON.stringify({project:'PHAROS',mode:'synthetic exercise',stage:state.stage,sources:SOURCES,hazards:hazards(state.stage),routes:checkRoutes(state.stage),draft:state.draft,activity:state.logs},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pharos-incident-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Incident report exported.');break}case 'connect':modal('Connect your Python backend',`<p>Run the included backend, then open its local dashboard for the simplest setup. For this hosted dashboard, use an HTTPS backend with this origin permitted by CORS. No credentials belong here.</p><label class="form-row">Backend URL<input id="api-url" placeholder="https://your-backend.example" value="${esc(state.api)}"></label><p>Connection enables server-side drafting and configured test delivery. Replay observations stay labeled as fixtures.</p><div class="actions">${btn('Use local mode','disconnect')}${btn('Test connection','test-connect','primary','plug')}</div>`);break;case 'disconnect':state.api='';state.connected=false;persist();$('#dialog').close();render();break;case 'test-connect':{const url=$('#api-url').value.trim().replace(/\/$/,'');try{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error('Use an HTTP or HTTPS URL.');state.api=url;await api('/api/health');state.connected=true;persist();$('#dialog').close();render();toast('Backend connected.')}catch(e){state.connected=false;toast(`Connection failed: ${e.message}`)}break}}
}
document.addEventListener('click',e=>{const ar=e.target.closest('[data-area]');if(ar){const id=ar.dataset.area;const i=state.selectedAreas.indexOf(id);if(i>=0)state.selectedAreas.splice(i,1);else state.selectedAreas.push(id);persist();render();return}const lg=e.target.closest('[data-lang]');if(lg){state.activeLang=lg.dataset.lang;persist();if($('#dialog').open)$('#dialog').close();render();return}const n=e.target.closest('[data-nav]');if(n){nav(n.dataset.nav);return}const r=e.target.closest('[data-route]');if(r){state.selectedRoute=r.dataset.route;const route=checkRoutes(state.stage).find(x=>x.id===r.dataset.route);if(state.page==='Overview')render();modal(route.name,`<span class="badge ${route.blocked?'orange':''}">${route.blocked?'Excluded by scenario geometry':'Passes supplied geometry check'}</span><p>${route.distance} · ${route.duration} · synthetic route fixture</p><p>Destination: ${route.destination}. Road conditions and destination availability are unverified. Geometry checks cannot establish evacuation safety.</p>`);return}const evidence=e.target.closest('[data-evidence]');if(evidence){const s=SOURCES.find(x=>x.id===evidence.dataset.evidence);modal(s.name,`<span class="badge orange">SYNTHETIC REPLAY SOURCE</span><p>${esc(s.detail)}</p><div class="info-grid"><div><span>Source ID</span><strong>${s.id}</strong></div><div><span>Scenario observation time</span><strong>${s.time} PDT</strong></div></div>`);return}const l=e.target.closest('[data-layer]');if(l){state.layer=l.dataset.layer;render();return}const a=e.target.closest('[data-action]');if(a)action(a.dataset.action)});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-evidence]')){e.preventDefault();e.target.click()}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
$('#schematic-fallback').innerHTML=schematicMap();
render();
fetch('data/districts.json').then(r=>r.json()).then(d=>{state.districts=d.features||[];state.districtMeta=d.metadata||{};updateMap(state);render()}).catch(()=>{});
initializeMap(id=>{const el=document.querySelector('[data-route="'+id+'"]');if(el)el.click()},geoid=>{const i=state.selectedAreas.indexOf(geoid);if(i>=0)state.selectedAreas.splice(i,1);else state.selectedAreas.push(geoid);persist();render()});
function loadPerimeters(){fetch((state.api||'')+'/api/live/perimeters?limit=25').then(r=>r.ok?r.json():null).then(d=>{if(d&&Array.isArray(d.perimeters)&&d.perimeters.length){state.perimeters={type:'FeatureCollection',features:d.perimeters};updateMap(state)}}).catch(()=>{})}
if(!presentationMode)loadPerimeters();
if(!presentationMode&&(location.hostname==='127.0.0.1'||location.hostname==='localhost')){state.api=location.origin;api('/api/health').then(()=>{state.connected=true;loadPerimeters();render()}).catch(()=>{})}else if(state.api){api('/api/health').then(()=>{state.connected=true;loadPerimeters();render()}).catch(()=>{})}

// Presentation controls operate on an isolated exercise session, never approvals or delivery.
if(presentationMode&&window.parent!==window){
 const presentationOrigin=location.origin;
 window.addEventListener('message',async event=>{
  if(!allowedBridge(event,presentationOrigin,window.parent))return;
  const command=event.data.command;
  if(command==='reset'||command==='closure'){
   clearInterval(timer);state.playing=false;state.stage=command==='closure'?2:0;state.draft=null;
   state.api='';state.connected=false;if($('#dialog').open)$('#dialog').close();
   log(command==='closure'?'Presentation closure loaded; prior draft and approval invalidated.':'Presentation scenario reset.');nav('Overview');
  }
  if(command==='draft'){if($('#dialog').open)$('#dialog').close();await draft();}
  event.source.postMessage({type:'PHAROS_PRESENTATION_ACK',command},event.origin);
 });
}
